{"code":"import numpy as np

# Suppose y is roughly quadratic in the ingredients around the optimum.
# In 1D (varying pea vs TVP by +-0.05 around 0.45/0.25), changing by 0.05 increased y by +0.1026!
# Between Iter 2 and Iter 5, pea changed by 0.10 (0.35 -> 0.45) and mycoprotein changed by -0.10 (0.15 -> 0.05),
# while TVP changed by +0.05 (0.20 -> 0.25).
# Yet BOTH Iter 2 (0.3548) and Iter 5 (0.3458) have almost the SAME low y (~0.35)!
# The ONLY way two points 0.10 apart in a high-curvature bowl have the same y (~0.35)
# is if they straddle the minimum along the segment connecting Iter 2 and Iter 5!

r2 = {"pea protein": 0.35, "textured vegetable protein": 0.20, "mycoprotein": 0.15, "canola oil": 0.12, "shea butter": 0.06, "potato starch": 0.04, "flavours": 0.04, "potato protein": 0.02, "fruit juice": 0.02}
r5 = {"pea protein": 0.45, "textured vegetable protein": 0.25, "mycoprotein": 0.05, "canola oil": 0.12, "shea butter": 0.04, "potato starch": 0.03, "flavours": 0.03, "potato protein": 0.02, "fruit juice": 0.01}

mid = {k: round(0.45 * r2[k] + 0.55 * r5[k], 4) for k in r2}
print("Interpolated (0.45*r2 + 0.55*r5):", mid, "sum:", sum(mid.values()))
"}

