    p = sum(v for k, v in r.items() if k in proteins)
    fn = sum(v for k, v in r.items() if k in fungi)
    o = sum(v for k, v in r.items() if k in oils)
    b = sum(v for k, v in r.items() if k in binders)
    fl = sum(v for k, v in r.items() if k in flavs)
